import { defineUserSignupFields } from "wasp/server/auth";

export const userSignupFields = defineUserSignupFields({
  role: (data: any) => {
    const role = data?.role;
    if (role === "ANALYST" || role === "MANAGER" || role === "ADMIN") {
      return role;
    }
    return "ANALYST";
  },
});

import { HttpError } from "wasp/server";
import type { OnBeforeSignupHook } from "wasp/server/auth";

export const onBeforeSignup: OnBeforeSignupHook = async ({
  providerId,
  prisma,
  req,
}) => {
  const username = req.body?.username || providerId.providerUserId;
  const role = req.body?.role;

  if (role === "ADMIN" && (!username || !username.endsWith("_admin"))) {
    throw new HttpError(403, "Admin username must end with _admin");
  }
};

import { HttpError } from "wasp/server";
import type {
  GetDocuments,
  GetAuditLogs,
  CreateDocument,
  UpdateDocument,
  DeleteDocument,
} from "wasp/server/operations";

export const getDocuments: GetDocuments<void, any> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  return context.entities.Document.findMany({
    orderBy: { id: "desc" },
  });
};

export const getAuditLogs: GetAuditLogs<void, any> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  if (context.user.role !== "ADMIN") {
    throw new HttpError(403, "Forbidden");
  }
  return context.entities.AuditLog.findMany({
    orderBy: { timestamp: "desc" },
  });
};

export const createDocument: CreateDocument<
  { title: string; content: string },
  any
> = async ({ title, content }, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  if (context.user.role !== "MANAGER" && context.user.role !== "ADMIN") {
    throw new HttpError(403, "Forbidden");
  }

  const doc = await context.entities.Document.create({
    data: {
      title,
      content,
      ownerId: context.user.id,
    },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "CREATE",
      entityName: "Document",
      entityId: doc.id,
      userId: context.user.id,
      payload: JSON.stringify({ title, content }),
    },
  });

  return doc;
};

export const updateDocument: UpdateDocument<
  { id: number; title: string; content: string },
  any
> = async ({ id, title, content }, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  if (context.user.role !== "MANAGER" && context.user.role !== "ADMIN") {
    throw new HttpError(403, "Forbidden");
  }

  const doc = await context.entities.Document.update({
    where: { id },
    data: {
      title,
      content,
    },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "UPDATE",
      entityName: "Document",
      entityId: id,
      userId: context.user.id,
      payload: JSON.stringify({ title, content }),
    },
  });

  return doc;
};

export const deleteDocument: DeleteDocument<{ id: number }, any> = async (
  { id },
  context
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  if (context.user.role !== "ADMIN") {
    throw new HttpError(403, "Forbidden");
  }

  await context.entities.Document.delete({
    where: { id },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "DELETE",
      entityName: "Document",
      entityId: id,
      userId: context.user.id,
      payload: JSON.stringify({ id }),
    },
  });
};

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import {
  getDocuments,
  getAuditLogs,
  createDocument,
  updateDocument,
  deleteDocument,
} from "./src/operations" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {
        userSignupFields: import { userSignupFields } from "./src/auth/signup" with { type: "ref" },
      },
    },
    onAuthFailedRedirectTo: "/login",
    onBeforeSignup: import { onBeforeSignup } from "./src/auth/hooks" with { type: "ref" },
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    query(getDocuments, { entities: ["Document"] }),
    query(getAuditLogs, { entities: ["AuditLog"] }),
    action(createDocument, { entities: ["Document", "AuditLog"] }),
    action(updateDocument, { entities: ["Document", "AuditLog"] }),
    action(deleteDocument, { entities: ["Document", "AuditLog"] }),
  ],
});

