        </div>
      </header>

      {error && <div style={{ color: "red", marginBottom: "1rem", border: "1px solid red", padding: "0.5rem" }}>{error}</div>}

      {/* Document Creation Form */}
      {canCreateOrUpdate && (
        <section style={{ marginBottom: "2rem", border: "1px solid #ccc", padding: "1.5rem", borderRadius: "4px" }}>
          <h2>Create Enterprise Document</h2>
          <form onSubmit={handleCreateDoc}>
            <div style={{ marginBottom: "1rem" }}>
              <label htmlFor="doc-title" style={{ display: "block", marginBottom: "0.5rem" }}>Title:</label>
              <input
                type="text"
                id="doc-title"
                value={docTitle}
                onChange={(e) => setDocTitle(e.target.value)}
                required
                style={{ width: "100%", padding: "0.5rem" }}
              />
            </div>
            <div style={{ marginBottom: "1rem" }}>
              <label htmlFor="doc-content" style={{ display: "block", marginBottom: "0.5rem" }}>Content:</label>
              <textarea
                id="doc-content"
                value={docContent}
                onChange={(e) => setDocContent(e.target.value)}
                required
                style={{ width: "100%", padding: "0.5rem", minHeight: "100px" }}
              />
            </div>
            <button type="submit" id="create-doc-btn" style={{ padding: "0.5rem 1rem" }}>
              Create Document
            </button>
          </form>
        </section>
      )}

      {/* Document List */}
      <section style={{ marginBottom: "2rem" }}>
        <h2>Enterprise Documents</h2>
        {docsLoading ? (
          <div>Loading documents...</div>
        ) : !documents || documents.length === 0 ? (
          <div>No documents found.</div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
            {documents.map((doc: any) => (
              <div key={doc.id} style={{ border: "1px solid #ddd", padding: "1rem", borderRadius: "4px" }}>
                <h3>{doc.title}</h3>
                <p>{doc.content}</p>
                <div style={{ marginTop: "1rem", display: "flex", gap: "0.5rem" }}>
                  <button
                    data-testid={`update-doc-btn-${doc.id}`}
                    onClick={() => handleUpdateDoc(doc)}
                    style={{ padding: "0.5rem 1rem" }}
                  >
                    Update
                  </button>
                  {isAdmin && (
                    <button
                      data-testid={`delete-doc-btn-${doc.id}`}
                      onClick={() => handleDeleteDoc(doc.id)}
                      style={{ padding: "0.5rem 1rem", backgroundColor: "#ff4d4d", color: "white", border: "none" }}
                    >
                      Delete
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Audit Logs Section */}
      {isAdmin && (
        <section style={{ borderTop: "2px solid #333", paddingTop: "2rem" }}>
          <h2>System Audit Logs</h2>
          {logsLoading ? (
            <div>Loading audit logs...</div>
          ) : !auditLogs || auditLogs.length === 0 ? (
            <div>No audit logs found.</div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
              {auditLogs.map((log: any) => (
                <div
                  key={log.id}
                  data-testid="audit-log-item"
                  style={{ border: "1px dashed #999", padding: "0.75rem", borderRadius: "4px", backgroundColor: "#f9f9f9" }}
                >
                  <div><strong>Action:</strong> {log.action}</div>
                  <div><strong>Entity Name:</strong> {log.entityName}</div>
                  <div><strong>Entity ID:</strong> {log.entityId}</div>
                  <div><strong>User ID:</strong> {log.userId}</div>
                  <div><strong>Payload:</strong> <code style={{ backgroundColor: "#eee", padding: "0.2rem" }}>{log.payload}</code></div>
                  <div style={{ fontSize: "0.8rem", color: "#666", marginTop: "0.25rem" }}>
                    {new Date(log.timestamp).toLocaleString()}
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      )}
    </div>
  );
}

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { userSignupFields } from "./src/auth/signup" with { type: "ref" };
import { onBeforeSignup } from "./src/auth/hooks" with { type: "ref" };
import {
  getDocuments,
  getAuditLogs,
  createDocument,
  updateDocument,
  deleteDocument,
} from "./src/operations" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {
        userSignupFields,
      },
    },
    onAuthFailedRedirectTo: "/login",
    onBeforeSignup,
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    query(getDocuments, { entities: ["Document"] }),
    query(getAuditLogs, { entities: ["AuditLog"] }),
    action(createDocument, { entities: ["Document", "AuditLog"] }),
    action(updateDocument, { entities: ["Document", "AuditLog"] }),
    action(deleteDocument, { entities: ["Document", "AuditLog"] }),
  ],
});

import React, { useState } from "react";
import { login } from "wasp/client/auth";
import { useNavigate, Link } from "react-router";

export const LoginPage = () => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
      await login({ username, password });
      navigate("/");
    } catch (err: any) {
      setError(err.message || "Login failed");
    }
  };

  return (
    <div style={{ padding: "2rem", maxWidth: "400px", margin: "0 auto" }}>
      <h2>Login</h2>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: "1rem" }}>
          <label htmlFor="username">Username: </label>
          <input
            type="text"
            id="username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
            style={{ width: "100%", padding: "0.5rem" }}
          />
        </div>
        <div style={{ marginBottom: "1rem" }}>
          <label htmlFor="password">Password: </label>
          <input
            type="password"
            id="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            style={{ width: "100%", padding: "0.5rem" }}
          />
        </div>
        {error && <div style={{ color: "red", marginBottom: "1rem" }}>{error}</div>}
        <button type="submit" id="login-btn" style={{ padding: "0.5rem 1rem" }}>
          Log In
        </button>
      </form>
      <p style={{ marginTop: "1rem" }}>
        Don't have an account? <Link to="/signup">Signup</Link>
      </p>
    </div>
  );
};

import React, { useState } from "react";
import { signup } from "wasp/client/auth";
import { useNavigate, Link } from "react-router";

export const SignupPage = () => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("ANALYST");
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
      await (signup as any)({ username, password, role });
      navigate("/");
    } catch (err: any) {
      setError(err.message || "Signup failed");
    }
  };

  return (
    <div style={{ padding: "2rem", maxWidth: "400px", margin: "0 auto" }}>
      <h2>Signup</h2>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: "1rem" }}>
          <label htmlFor="username">Username: </label>
          <input
            type="text"
            id="username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
            style={{ width: "100%", padding: "0.5rem" }}
          />
        </div>
        <div style={{ marginBottom: "1rem" }}>
          <label htmlFor="password">Password: </label>
          <input
            type="password"
            id="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            style={{ width: "100%", padding: "0.5rem" }}
          />
        </div>
        <div style={{ marginBottom: "1rem" }}>
          <label htmlFor="role">Role: </label>
          <select
            id="role"
            value={role}
            onChange={(e) => setRole(e.target.value)}
            style={{ width: "100%", padding: "0.5rem" }}
          >
            <option value="ANALYST">ANALYST</option>
            <option value="MANAGER">MANAGER</option>
            <option value="ADMIN">ADMIN</option>
          </select>
        </div>
        {error && <div style={{ color: "red", marginBottom: "1rem" }}>{error}</div>}
        <button type="submit" id="signup-btn" style={{ padding: "0.5rem 1rem" }}>
          Sign Up
        </button>
      </form>
      <p style={{ marginTop: "1rem" }}>
        Already have an account? <Link to="/login">Login</Link>
      </p>
    </div>
  );
};
